styles:
.b-services {
    container-type: inline-size;
}

.b-services__title {
    margin: 0 0 1em;
}

.b-services__filter {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5em;
    margin: 0 0 1.25em;
}

/* A flex box outranks the browser's own [hidden] rule. */
.b-services__filter[hidden],
.b-services__card[hidden] {
    display: none;
}

.b-services__chip {
    font: inherit;
    color: inherit;
    background: none;
    border: 1px solid currentColor;
    border-radius: 999px;
    padding: 0.35em 0.9em;
    cursor: pointer;
    opacity: 0.65;
}

.b-services__chip.is-active {
    opacity: 1;
    font-weight: 600;
}

.b-services__grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(16rem, 1fr));
    gap: 1.5em;
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-services__link {
    display: flex;
    flex-direction: column;
    gap: 0.75em;
    color: inherit;
    text-decoration: none;
}

.b-services__cover {
    width: 100%;
    height: auto;
    aspect-ratio: 4 / 3;
    object-fit: cover;
    border-radius: 0.5em;
}

.b-services__name {
    font-weight: 600;
    font-size: 1.125em;
}

.b-services__link:hover .b-services__name {
    text-decoration: underline;
}

.b-services__lead {
    margin: 0.5em 0 0;
    opacity: 0.8;
}

script:
const cards = Array.from(el.querySelectorAll('.b-services__card'))
const chips = Array.from(el.querySelectorAll('.b-services__chip'))
const filter = el.querySelector('.b-services__filter')

// The filter is printed hidden: without this script its buttons would do nothing.
if (filter) filter.hidden = false

for (const chip of chips) {
  chip.addEventListener('click', () => {
    const group = chip.dataset.servicesGroup || ''
    for (const other of chips) {
      const on = other === chip
      other.classList.toggle('is-active', on)
      other.setAttribute('aria-pressed', on ? 'true' : 'false')
    }
    for (const card of cards) {
      const groups = (card.dataset.servicesCategories || '').split(' ')
      card.hidden = group !== '' && !groups.includes(group)
    }
  })
}
